import { StringColumn, IntegerColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables with simple inline scripts
 * Tests basic inline script functionality in setFlowVariables
 */
export const setFlowVariablesInlineScriptSimple = Flow(
    {
        $id: Now.ID['set-flow-variables-inline-script-simple'],
        name: 'SetFlowVariables Inline Script Simple Test',
        description: 'Test SetFlowVariables with simple inline script values',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            greeting: StringColumn({
                label: 'Greeting Message',
                mandatory: false,
            }),
            timestamp: StringColumn({
                label: 'Timestamp',
                mandatory: false,
            }),
            randomNumber: IntegerColumn({
                label: 'Random Number',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-inline-simple-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-inline-simple-instance'],
                annotation: 'Set variables with simple inline scripts',
            },
            params.flowVariables,
            {
                greeting: wfa.inlineScript("return 'Hello from inline script!'"),
                timestamp: wfa.inlineScript('return new Date().toISOString()'),
                randomNumber: wfa.inlineScript('return Math.floor(Math.random() * 100)'),
            }
        )
    }
)
